import{_ as r,C as d,c as a,o as n,aa as h,G as e}from"./chunks/framework.Cn7WEiMX.js";const g=JSON.parse('{"title":"TerraScript 函数","description":"","frontmatter":{},"headers":[],"relativePath":"wiki/Terra/config-packs/config-documentation/terra-script/terrascript-functions.md","filePath":"wiki/Terra/config-packs/config-documentation/terra-script/terrascript-functions.md"}'),s={name:"wiki/Terra/config-packs/config-documentation/terra-script/terrascript-functions.md"};function i(l,t,p,u,b,m){const o=d("NolebaseGitContributors"),c=d("NolebaseGitChangelog");return n(),a("div",null,[t[0]||(t[0]=h(`<h1 id="terrascript-函数" tabindex="-1">TerraScript 函数 <a class="header-anchor" href="#terrascript-函数" aria-label="Permalink to &quot;TerraScript 函数&quot;">​</a></h1> <p>Terra 的 TerraScript 实现包含了许多与世界交互、设置数据及调试相关的函数。</p> <h2 id="方块-block" tabindex="-1">方块（block） <a class="header-anchor" href="#方块-block" aria-label="Permalink to &quot;方块（block）&quot;">​</a></h2> <p>block 函数可以在指定位置放置方块。</p> <p>参数：</p> <table tabindex="0"><thead><tr><th>参数</th> <th>类型</th> <th>描述</th></tr></thead> <tbody><tr><td><code>x</code></td> <td><code>num</code></td> <td>放置方块（相对于原点）的 X 坐标</td></tr> <tr><td><code>y</code></td> <td><code>num</code></td> <td>放置方块（相对于原点）的 Y 坐标</td></tr> <tr><td><code>z</code></td> <td><code>num</code></td> <td>放置方块（相对于原点）的 Z 坐标</td></tr> <tr><td><code>data</code></td> <td><code>str</code></td> <td>放置方块包含的方块数据字符串（必须为常量表达式）</td></tr> <tr><td><code>replace</code></td> <td><code>bool</code></td> <td>（可选；默认值为 <code>true</code>）设置为 true 时，替换现存方块。在这种情况下，任何方块都会被覆写（此参数未指定时的默认行为）。当为 false 时，只有空气才会被替换。</td></tr> <tr><td><code>physics</code></td> <td><code>bool</code></td> <td>（可选：默认值为 <code>false</code>）是否在初始区块生成后为方块进行一次刻更新，使得诸如水或沙子等方块可以流动或下坠。</td></tr></tbody></table> <p>返回类型：<code>void</code></p> <h2 id="检查-check" tabindex="-1">检查（check） <a class="header-anchor" href="#检查-check" aria-label="Permalink to &quot;检查（check）&quot;">​</a></h2> <p>check 函数检查位置的“类型”。它可以更快地检测指定位置是否在空中、海洋或地面。它无法获取指定位置的方块状态信息，因此它比 <code>getBlock</code> 快许多，且不会强行加载它使用的区块。在普通结构中应避免使用 <code>getBlock</code>，并尽可能将其替换为 <code>check</code>。</p> <p>参数：</p> <table tabindex="0"><thead><tr><th>参数</th> <th>类型</th> <th>描述</th></tr></thead> <tbody><tr><td><code>x</code></td> <td><code>num</code></td> <td>检查方块（相对于原点）的 X 坐标</td></tr> <tr><td><code>y</code></td> <td><code>num</code></td> <td>检查方块（相对于原点）的 Y 坐标</td></tr> <tr><td><code>z</code></td> <td><code>num</code></td> <td>检查方块（相对于原点）的 Z 坐标</td></tr></tbody></table> <p>返回类型：<code>STRING</code> - 传入坐标的位置类型，基于结构原点。</p> <p><strong>只会</strong>返回如下之一：</p> <ul><li><code>AIR</code> - 位置在空中。</li> <li><code>LAND</code> - 位置在地面上。</li> <li><code>OCEAN</code> - 位置在海洋中。</li></ul> <h2 id="结构-structure" tabindex="-1">结构（structure） <a class="header-anchor" href="#结构-structure" aria-label="Permalink to &quot;结构（structure）&quot;">​</a></h2> <p>structure 函数会在当前结构中生成另一个<a href="./../config-objects/structure">结构</a>，带原点偏移及旋转。</p> <p>参数：</p> <table tabindex="0"><thead><tr><th>参数</th> <th>类型</th> <th>描述</th></tr></thead> <tbody><tr><td><code>x</code></td> <td><code>num</code></td> <td>放置结构（相对于原点）的 X 坐标</td></tr> <tr><td><code>y</code></td> <td><code>num</code></td> <td>放置结构（相对于原点）的 Y 坐标</td></tr> <tr><td><code>z</code></td> <td><code>num</code></td> <td>放置结构（相对于原点）的 Z 坐标</td></tr> <tr><td><code>structure</code></td> <td><code>str</code></td> <td>生成的结构 ID（等同于结构脚本中的 <code>id</code>）</td></tr> <tr><td><code>rotation</code></td> <td><code>str...</code></td> <td>生成结构时附带的旋转角度。会随机选择其中一个。有效旋转角度：<code>NONE</code>（不旋转）、<code>CW_90</code>（顺时针旋转 90 度）、<code>CCW_90</code>（逆时针旋转 90 度）以及 <code>CW_180</code>（旋转 180 度）</td></tr></tbody></table> <p><code>rotation</code> 中的 <code>...</code> 表示它是<em>可变参数</em> - 能够是任何数字值。</p> <p>返回类型：<code>BOOLEAN</code> - 若结构成功生成，则返回 <code>true</code>，反之返回 <code>false</code>。</p> <h2 id="随机整数-randomint" tabindex="-1">随机整数（randomInt） <a class="header-anchor" href="#随机整数-randomint" aria-label="Permalink to &quot;随机整数（randomInt）&quot;">​</a></h2> <p>randomInt 函数会返回指定范围内的随机整数。</p> <p>参数：</p> <table tabindex="0"><thead><tr><th>参数</th> <th>类型</th> <th>描述</th></tr></thead> <tbody><tr><td><code>range</code></td> <td><code>num</code></td> <td>最大值（不含）</td></tr></tbody></table> <p>返回类型：<code>NUMBER</code> - 范围为 <code>0</code>（含）至 <code>range</code> 对应值（不含）的随机整数。</p> <p>例如，<code>randomInt(10)</code> 会返回 <code>0</code> 到 <code>9</code> 的随机数。</p> <h2 id="递归-recursions" tabindex="-1">递归（recursions） <a class="header-anchor" href="#递归-recursions" aria-label="Permalink to &quot;递归（recursions）&quot;">​</a></h2> <p>recursions 函数获取前几次结构生成的递归次数。可有效防止递归结构无限递归。</p> <p>参数：无</p> <p>返回：<code>NUMBER</code> - 当前递归次数。</p> <p>若 <code>structure_a</code> 通过 <code>structure</code> 函数生成了 <code>structure_b</code>，则 <code>recursions()</code> 函数在 <code>structure_a</code> 中返回 <code>0</code>，而在 <code>structure_b</code> 中返回 <code>1</code>。若 <code>structure_b</code> 再次生成了 <code>structure_a</code>，则 <code>recursions()</code> 函数只会在<em>第二个生成的 <code>strucrure_a</code> 中</em>返回 <code>2</code>。</p> <h2 id="设置标记-setmark" tabindex="-1">设置标记（setMark） <a class="header-anchor" href="#设置标记-setmark" aria-label="Permalink to &quot;设置标记（setMark）&quot;">​</a></h2> <p>setMark 函数是与标记交互的一种方式，允许数据存储在结构中备用，而不会影响其正常生成。标记是分配给指定位置结构的一串字符。由 <code>setMark</code> 函数设置，通过 <code>getMark</code> 读取。其中一种使用方式就是通过标记位置决定结构生成的位置，然后用 <code>getMark</code> 分别检查它们是否会重叠。</p> <p>递归结构中的标记在父结构中可见。若 <code>structure_a</code> 通过 <code>structure</code> 函数生成了 <code>structure_b</code>，且 <code>structure_b</code> 设置了一个标记，则 <code>structure_a</code> 可以读取这个标记。标记的位置是相对的，会设置在所有递归的偏移原点上。</p> <p>在已有位置上重复设置标记会使得新标记覆盖旧标记的值。</p> <p>参数：</p> <table tabindex="0"><thead><tr><th>参数</th> <th>类型</th> <th>描述</th></tr></thead> <tbody><tr><td><code>x</code></td> <td><code>num</code></td> <td>设置标记（相对于原点）的 X 坐标</td></tr> <tr><td><code>y</code></td> <td><code>num</code></td> <td>设置标记（相对于原点）的 Y 坐标</td></tr> <tr><td><code>z</code></td> <td><code>num</code></td> <td>设置标记（相对于原点）的 Z 坐标</td></tr> <tr><td><code>content</code></td> <td><code>str</code></td> <td>设置标记的内容</td></tr></tbody></table> <p>返回类型：<code>VOID</code></p> <h2 id="读取标记-getmark" tabindex="-1">读取标记（getMark） <a class="header-anchor" href="#读取标记-getmark" aria-label="Permalink to &quot;读取标记（getMark）&quot;">​</a></h2> <p>getMark 函数是与标记交互的一种方式，允许数据存储在结构中备用，而不会影响其正常生成。标记是分配给指定位置结构的一串字符。由 <code>setMark</code> 函数设置，通过 <code>getMark</code> 读取。其中一种使用方式就是通过标记位置决定结构生成的位置，然后用 <code>getMark</code> 分别检查它们是否会重叠。</p> <p>递归结构中的标记在父结构中可见。若 <code>structure_a</code> 通过 <code>structure</code> 函数生成了 <code>structure_b</code>，且 <code>structure_b</code> 设置了一个标记，则 <code>structure_a</code> 可以读取这个标记。标记的位置是相对的，会设置在所有递归的偏移原点上。</p> <p>参数：</p> <table tabindex="0"><thead><tr><th>参数</th> <th>类型</th> <th>描述</th></tr></thead> <tbody><tr><td><code>x</code></td> <td><code>num</code></td> <td>检查标记（相对于原点）的 X 坐标</td></tr> <tr><td><code>y</code></td> <td><code>num</code></td> <td>检查标记（相对于原点）的 Y 坐标</td></tr> <tr><td><code>z</code></td> <td><code>num</code></td> <td>检查标记（相对于原点）的 Z 坐标</td></tr></tbody></table> <p>返回类型：<code>STRING</code> - 对应位置的标记内容。如果标记为空或不存在，则返回 <code>&quot;&quot;</code>（空字符串）。</p> <h2 id="拉取-pull" tabindex="-1">拉取（pull） <a class="header-anchor" href="#拉取-pull" aria-label="Permalink to &quot;拉取（pull）&quot;">​</a></h2> <p>pull 函数会在指定位置放置方块，然后将其“拉”到地面。pull 函数首先会搜索指定位置，然后向下延伸，直到检测到下方方块不是空气为止。</p> <p>参数：</p> <table tabindex="0"><thead><tr><th>参数</th> <th>类型</th> <th>描述</th></tr></thead> <tbody><tr><td><code>x</code></td> <td><code>num</code></td> <td>放置方块（相对于原点）的 X 坐标</td></tr> <tr><td><code>y</code></td> <td><code>num</code></td> <td>开始搜索（相对于原点）的 Y 坐标</td></tr> <tr><td><code>z</code></td> <td><code>num</code></td> <td>放置方块（相对于原点）的 Z 坐标</td></tr> <tr><td><code>data</code></td> <td><code>str</code></td> <td>放置方块的方块数据（必须为常量表达式）</td></tr></tbody></table> <p>返回类型：<code>VOID</code></p> <h2 id="战利品-loot" tabindex="-1">战利品（loot） <a class="header-anchor" href="#战利品-loot" aria-label="Permalink to &quot;战利品（loot）&quot;">​</a></h2> <p>loot 函数会对某个箱子填充战利品。容器为任意带有界面的方块（箱子、潜影盒、熔炉、酿造台等）。</p> <p>参数：</p> <table tabindex="0"><thead><tr><th>参数</th> <th>类型</th> <th>描述</th></tr></thead> <tbody><tr><td><code>x</code></td> <td><code>num</code></td> <td>填充战利品（相对于原点）的 X 坐标</td></tr> <tr><td><code>y</code></td> <td><code>num</code></td> <td>填充战利品（相对于原点）的 Y 坐标</td></tr> <tr><td><code>z</code></td> <td><code>num</code></td> <td>填充战利品（相对于原点）的 Z 坐标</td></tr> <tr><td><code>table</code></td> <td><code>str</code></td> <td>战利品表的问文件名称，相对 <code>pack/structures/loot</code> 的路径。<br>示例：<code>village/village_house.json</code></td></tr></tbody></table> <p>返回类型：<code>VOID</code></p> <h2 id="实体-entity" tabindex="-1">实体（entity） <a class="header-anchor" href="#实体-entity" aria-label="Permalink to &quot;实体（entity）&quot;">​</a></h2> <p>entity 函数会在指定位置生成实体。</p> <table tabindex="0"><thead><tr><th>参数</th> <th>类型</th> <th>描述</th></tr></thead> <tbody><tr><td><code>x</code></td> <td><code>num</code></td> <td>生成实体（相对于原点）的 X 坐标</td></tr> <tr><td><code>y</code></td> <td><code>num</code></td> <td>生成实体（相对于原点）的 Y 坐标</td></tr> <tr><td><code>z</code></td> <td><code>num</code></td> <td>生成实体（相对于原点）的 Z 坐标</td></tr> <tr><td><code>entity</code></td> <td><code>str</code></td> <td>生成的实体 ID</td></tr></tbody></table> <p>返回类型：<code>VOID</code></p> <h2 id="获取群系-getbiome" tabindex="-1">获取群系（getBiome） <a class="header-anchor" href="#获取群系-getbiome" aria-label="Permalink to &quot;获取群系（getBiome）&quot;">​</a></h2> <p>getBiome 函数会返回指定位置的 Terra 群系。</p> <p>参数：</p> <table tabindex="0"><thead><tr><th>参数</th> <th>类型</th> <th>描述</th></tr></thead> <tbody><tr><td><code>x</code></td> <td><code>num</code></td> <td>检查群系（相对于原点）的 X 坐标</td></tr> <tr><td><code>y</code></td> <td><code>num</code></td> <td>检查群系（相对于原点）的 Y 坐标</td></tr> <tr><td><code>z</code></td> <td><code>num</code></td> <td>检查群系（相对于原点）的 Z 坐标</td></tr></tbody></table> <p>返回类型：<code>STRING</code> - 群系 ID，如 <code>&quot;ARID_MOUNTAINS&quot;</code></p> <h2 id="获取方块-getblock" tabindex="-1">获取方块（getBlock） <a class="header-anchor" href="#获取方块-getblock" aria-label="Permalink to &quot;获取方块（getBlock）&quot;">​</a></h2> <p>getBlock 函数检查指定位置的方块状态。<strong>它不应被用在普通结构中！</strong></p> <p>getBlock 函数首先会强加载区块。生成树木时无伤大雅，因为这些区块必定被夹在，但在普通结构中这会导致巨量的区块载入。<strong>请在普通结构中使用 <code>check</code> 函数，而非 <code>getBlock</code>！</strong></p> <p>参数：</p> <table tabindex="0"><thead><tr><th>参数</th> <th>类型</th> <th>描述</th></tr></thead> <tbody><tr><td><code>x</code></td> <td><code>num</code></td> <td>检查方块（相对于原点）的 X 坐标</td></tr> <tr><td><code>y</code></td> <td><code>num</code></td> <td>检查方块（相对于原点）的 Y 坐标</td></tr> <tr><td><code>z</code></td> <td><code>num</code></td> <td>检查方块（相对于原点）的 Z 坐标</td></tr></tbody></table> <p>返回类型：<code>STRING</code> - 方块的 ID，不带属性，如 <code>&quot;minecraft:stone&quot;</code>。</p> <h2 id="状态-state" tabindex="-1">状态（state） <a class="header-anchor" href="#状态-state" aria-label="Permalink to &quot;状态（state）&quot;">​</a></h2> <p>state 函数会将 NBT 数据施在方块实体（如告示牌或刷怪笼）上。</p> <p>数据格式为 <code>&quot;键甲=值甲,键乙=值乙&quot;</code>，如  <code>&quot;text1=hello,text2=world&quot;</code>，将其应用至告示牌会让告示牌显示如下内容：</p> <div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>hello</span></span>
<span class="line"><span>world</span></span></code></pre></div><p>参数：</p> <table tabindex="0"><thead><tr><th>参数</th> <th>类型</th> <th>描述</th></tr></thead> <tbody><tr><td><code>x</code></td> <td><code>num</code></td> <td>方块（相对于原点）的 X 坐标</td></tr> <tr><td><code>y</code></td> <td><code>num</code></td> <td>方块（相对于原点）的 Y 坐标</td></tr> <tr><td><code>z</code></td> <td><code>num</code></td> <td>方块（相对于原点）的 Z 坐标</td></tr> <tr><td><code>data</code></td> <td><code>str</code></td> <td>应用至方块的数据</td></tr></tbody></table> <p>返回类型：<code>VOID</code></p> <h2 id="输出-print" tabindex="-1">输出（print） <a class="header-anchor" href="#输出-print" aria-label="Permalink to &quot;输出（print）&quot;">​</a></h2> <p>print 函数会向控制台输出指定内容。它是调试用功能，只会在调试模式启用时生效。</p> <p>参数：</p> <table tabindex="0"><thead><tr><th>参数</th> <th>类型</th> <th>描述</th></tr></thead> <tbody><tr><td><code>message</code></td> <td><code>str</code></td> <td>输出至控制台的消息</td></tr></tbody></table> <h2 id="采样器-sampler" tabindex="-1">采样器（sampler） <a class="header-anchor" href="#采样器-sampler" aria-label="Permalink to &quot;采样器（sampler）&quot;">​</a></h2> <p>sampler 函数允许配置包缓存的<a href="./../config-objects/noisesampler">噪声采样器</a>在 TerraScript 中使用，并输出噪声值。</p> <p>参数：</p> <table tabindex="0"><thead><tr><th>参数</th> <th>类型</th> <th>描述</th></tr></thead> <tbody><tr><td><code>sampler</code></td> <td><code>str</code></td> <td>噪声采样器的 ID</td></tr> <tr><td><code>x</code></td> <td><code>num</code></td> <td>噪声输入的（相对于原点）的 X 坐标</td></tr> <tr><td><code>z</code></td> <td><code>num</code></td> <td>噪声输入的（相对于原点）的 Z 坐标</td></tr> <tr><td><code>y</code></td> <td><code>num</code></td> <td>（可选）噪声输入的（相对于原点）的 Y 坐标</td></tr></tbody></table> <p>返回类型：<code>num</code> - <a href="./../config-objects/noisesampler">噪声采样器</a>的输出值。</p> <p>由 <code>terrascript-function-sampler</code> 拓展提供。</p> `,171)),e(o),e(c)])}const x=r(s,[["render",i]]);export{g as __pageData,x as default};
